19	@@ -0,0 +1,89 @@
20	+/* ===== Trò chuyện theo khoảng cách (D-041): lõi phía khách (không DOM, không three) =====
21	+   Sổ tin của phiên (tin mình chờ hồi âm, tin người khác, chưa đọc, giới hạn tần suất) và danh sách người ở gần có trễ hai ngưỡng.
22	+   Mọi con số truyền vào từ multiParams.chat; phần DOM (chat.ts) chỉ vẽ theo những gì ở đây trả ra. */
23	+import type { ChatWhy, Kind } from './protocol';
24	+
25	+/* pending: chờ chatAck; ok: đã tới n ≥ 1 người; alone: không ai ở gần (n = 0); fail: quá hạn / mất kết nối / không giữ chỗ / rỗng; rate: gửi quá nhanh; bad: có từ tục */
26	+export type ChState = 'pending' | 'ok' | 'alone' | 'fail' | 'rate' | 'bad';
27	+// key: số thứ tự duy nhất trong phiên (khóa DOM); id: số ghép chatAck (chỉ tin mình, tin người khác 0); tin mình: k 'fly', slot −1, name '' (bên vẽ dựa vào mine); at: giờ thêm (ms)
28	+export interface ChMsg { key: number; id: number; mine: boolean; k: Kind; slot: number; name: string; text: string; at: number; state: ChState; n: number }
29	+// Người khác cùng phòng: vị trí nội suy (m)
30	+export interface ChPeer { k: Kind; slot: number; name: string; x: number; y: number; z: number }
31	+
32	+/* Khóa một người: loại + slot (ba nhóm slot riêng nên cùng slot khác loại là hai người) */
33	+export const chKey = (k: Kind, slot: number): string => k + ':' + slot;
34	+
35	+/* Người ở gần (trễ hai ngưỡng): vào khi d ≤ nearIn, đã có trong prev thì ở lại tới d ≤ radius; khoảng cách 3D từ vị trí mình vừa gửi; giữ thứ tự peers */
36	+export function chNear(self: { x: number; y: number; z: number } | null, peers: ChPeer[], prev: ReadonlySet<string>, nearIn: number, radius: number): ChPeer[] {
37	+  if (!self) return [];
38	+  const out: ChPeer[] = [];
39	+  for (const p of peers) {
40	+    const dx = p.x - self.x, dy = p.y - self.y, dz = p.z - self.z;
41	+    const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
42	+    if (d <= nearIn || (d <= radius && prev.has(chKey(p.k, p.slot)))) out.push(p);
43	+  }
44	+  return out;
45	+}
46	+
47	+/* ===== Sổ tin của một phiên (chỉ trong bộ nhớ; phiên mới thì clear) ===== */
48	+export class ChLog {
49	+  readonly list: ChMsg[] = [];
50	+  unread = 0;
51	+  private nextKey = 1;    // không đặt lại khi clear: khóa DOM không lặp
52	+  private nextId = 1;
53	+  private sent: number[] = [];   // giờ các tin mình đã gửi trong rateWinMs gần nhất (cùng cách tính với máy chủ)
54	+
55	+  constructor(private historyMax: number, private ackMs: number, private ratePerWin: number, private rateWinMs: number) {}
56	+
57	+  /* Hạn mức phía khách: < ratePerWin tin trong cửa sổ trượt rateWinMs (máy chủ cũng chặn, đây chỉ để khỏi gửi tin chắc chắn bị từ chối) */
58	+  canSend(now: number): boolean {
59	+    this.sent = this.sent.filter(t => now - t < this.rateWinMs);
60	+    return this.sent.length < this.ratePerWin;
61	+  }
62	+
63	+  addMine(text: string, now: number): ChMsg {
64	+    const m: ChMsg = { key: this.nextKey++, id: this.nextId++, mine: true, k: 'fly', slot: -1, name: '', text, at: now, state: 'pending', n: 0 };
65	+    this.list.push(m); this.sent.push(now);
66	+    return m;
67	+  }
68	+
69	+  addTheirs(k: Kind, slot: number, name: string, text: string, now: number, panelOpen: boolean): ChMsg {
70	+    const m: ChMsg = { key: this.nextKey++, id: 0, mine: false, k, slot, name, text, at: now, state: 'ok', n: 0 };
71	+    this.list.push(m);
72	+    if (!panelOpen) this.unread++;
73	+    return m;
74	+  }
75	+
76	+  /* Hồi âm: chỉ đổi tin mình đang pending (hồi âm trễ sau khi đã fail không đổi lại); trả tin vừa đổi, null nếu không có */
77	+  ack(id: number, n: number | undefined, why: ChatWhy | undefined): ChMsg | null {
78	+    const m = this.list.find(x => x.mine && x.id === id && x.state === 'pending');
79	+    if (!m) return null;
80	+    if (typeof n === 'number' && n >= 1) { m.state = 'ok'; m.n = n; }
81	+    else if (n === 0) m.state = 'alone';
82	+    else m.state = why === 'rate' ? 'rate' : why === 'bad' ? 'bad' : 'fail';
83	+    return m;
84	+  }
85	+
86	+  /* Tin pending đã chờ ≥ ackMs thành fail; trả các tin vừa đổi */
87	+  expire(now: number): ChMsg[] {
88	+    const out: ChMsg[] = [];
89	+    for (const m of this.list) if (m.state === 'pending' && now - m.at >= this.ackMs) { m.state = 'fail'; out.push(m); }
90	+    return out;
91	+  }
92	+
93	+  /* Mất kết nối: mọi tin pending thành fail */
94	+  failAll(): ChMsg[] {
95	+    const out: ChMsg[] = [];
96	+    for (const m of this.list) if (m.state === 'pending') { m.state = 'fail'; out.push(m); }
97	+    return out;
98	+  }
99	+
100	+  /* Gỡ tin cũ nhất tới khi còn ≤ historyMax; trả tin bị gỡ (bên vẽ xóa phần tử DOM tương ứng) */
101	+  trim(): ChMsg[] {
102	+    return this.list.length > this.historyMax ? this.list.splice(0, this.list.length - this.historyMax) : [];
103	+  }
104	+
105	+  read(): void { this.unread = 0; }
106	+
107	+  clear(): void { this.list.length = 0; this.unread = 0; this.sent = []; }
108	+}
